{
  "plan": [
    "Replace the `normalizeMarkdown` function to ensure that fenced code blocks remain literal while other text retains its current plain-text rendering."
  ],
  "hypothesis": "The current `normalizeMarkdown` function is incorrectly processing fenced code blocks, leading to corruption.",
  "patches": [
    {
      "file": "backend/src/mentor-answer-format.js",
      "oldText": "const TRUNCATION_NOTICE = "\n\n[Antwort gekürzt. Bitte frage nach einem einzelnen Teilthema.]";
const INCOMPLETE_NOTICE = "\n\n[Die Modellausgabe endete am Tokenlimit. Für den fehlenden Teil bitte nachfragen.]";

function normalizeMarkdown(text) {
  const normalized = text.replace(/\r\n?/g, "\n");
  const lines = normalized.split("\n").map(line => {
    const trimmed = line.trim();
    // Android intentionally renders text, not Markdown. Preserve table values.
    if (trimmed.startsWith("|") && trimmed.endsWith("|") && trimmed.length > 2) {
      const cells = trimmed.slice(1, -1).split("|")
        .map(cell => cell.trim().replace(/\*\*([^*\n]+)\*\*/g, "$1"));
      if (cells.every(cell => /^:?-{3,}:?$/.test(cell))) return "";
      if (cells.length >= 2) return cells[0] + ": " + cells.slice(1).join(" — ");
    }
    return line.replace(/^\s{0,3}#{1,6}\s+/u, "")
      .replace(/\*\*([^*\n]+)\*\*/g, "$1")
      .trimEnd();
  });
  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}
